def isAcronym(words: list[str], s: str) -> bool:
    # Check if the number of words matches the length of s
    if len(words) != len(s):
        return False

    # Iterate through each word and compare its first character with s at the same index
    for i in range(len(words)):
        if words[i][0] != s[i]:
            return False

    return True
