import sys

def solve():
    # Read all input at once for performance
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    it = iter(input_data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # The condition b_i^{b_j} = b_j^{b_i} where b_i = 2^{a_i} and b_j = 2^{a_j}
        # translates to: (2^{a_i})^{2^{a_j}} = (2^{a_j})^{2^{a_i}}
        # Applying log2: 2^{a_j} * a_i = 2^{a_i} * a_j
        # Dividing: a_i / 2^{a_i} = a_j / 2^{a_j}

        # Analyzing the function f(x) = x / 2^x:
        # f(1) = 1/2
        # f(2) = 2/4 = 1/2
        # For all other positive integers, the values are unique.
        # So a_i and a_j satisfy the condition if:
        # 1. a_i == a_j
        # 2. {a_i, a_j} == {1, 2}

        counts = {}
        for x in a:
            counts[x] = counts.get(x, 0) + 1

        ans = 0

        # Count pairs where a_i == a_j
        for val in counts:
            count = counts[val]
            if count > 1:
                ans += (count * (count - 1)) // 2

        # Count special case pairs {1, 2}
        if 1 in counts and 2 in counts:
            ans += counts[1] * counts[2]

        print(ans)

if __name__ == "__main__":
    solve()
```

