def isValid(word: str) -> bool:
    # A word is considered valid if it contains a minimum of 3 characters.
    if len(word) < 3:
        return False

    vowels = set("aeiouAEIOU")
    has_vowel = False
    has_consonant = False

    for char in word:
        # It contains only digits (0-9), and English letters (uppercase and lowercase).
        if not char.isalnum():
            return False

        if char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                # A consonant is an English letter that is not a vowel.
                has_consonant = True

    # It must include at least one vowel and at least one consonant.
    return has_vowel and has_consonant
```

