import sys

def solve():
    # Read N and M from the first line
    try:
        line1 = sys.stdin.readline().split()
        if not line1:
            return
        n, m = map(int, line1)
        # Read the schedule string S
        s = sys.stdin.readline().strip()
    except EOFError:
        return

    # We need to find the minimum number of logo T-shirts 'k'
    # that satisfy all conditions. We can iterate through possible values of k.
    # Since N is up to 1000, we can check from 0 up to N.

    def check(k):
        plain_ready = m
        logo_ready = k

        for char in s:
            if char == '0':
                # Reset all shirts
                plain_ready = m
                logo_ready = k
            elif char == '1':
                # Meal: Use plain if available, else logo
                if plain_ready > 0:
                    plain_ready -= 1
                elif logo_ready > 0:
                    logo_ready -= 1
                else:
                    return False
            elif char == '2':
                # Event: Must use logo
                if logo_ready > 0:
                    logo_ready -= 1
                else:
                    return False
        return True

    # Binary search for the minimum k or simple linear search
    for k in range(n + 1):
        if check(k):
            print(k)
            return

if __name__ == "__main__":
    solve()
```

