    min_ops = float('inf')
    found = False

    # Check horizontal sequences
    if W >= K:
        for i in range(H):
            row = S[i]
            x_count = 0
            dot_count = 0
            # Use sliding window of size K
            for j in range(W):
                if row[j] == 'x':
                    x_count += 1
                elif row[j] == '.':
                    dot_count += 1

                if j >= K:
                    if row[j-K] == 'x':
                        x_count -= 1
                    elif row[j-K] == '.':
                        dot_count -= 1

                if j >= K - 1:
                    if x_count == 0:
                        found = True
                        if dot_count < min_ops:
                            min_ops = dot_count

    # Check vertical sequences
    if H >= K:
        for j in range(W):
            x_count = 0
            dot_count = 0
            # Use sliding window of size K
            for i in range(H):
                char = S[i][j]
                if char == 'x':
                    x_count += 1
                elif char == '.':
                    dot_count += 1

                if i >= K:
                    prev_char = S[i-K][j]
                    if prev_char == 'x':
                        x_count -= 1
                    elif prev_char == '.':
                        dot_count -= 1

                if i >= K - 1:
                    if x_count == 0:
                        found = True
                        if dot_count < min_ops:
                            min_ops = dot_count

